<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Vendor extends Model{protected $fillable=['user_id','business_name','slug','description','status','commission_rate','balance','phone','address'];protected $casts=['commission_rate'=>'decimal:2','balance'=>'decimal:2'];public function user(){return $this->belongsTo(User::class);}public function products(){return $this->belongsToMany(Product::class,'vendor_products');}public function payouts(){return $this->hasMany(VendorPayout::class);}public function ratings(){return $this->hasMany(VendorRating::class);}}
